//! Source files a tool wrote, which the index leaves out: a bundle (`extension.js` that esbuild or bun built from
//! `src/`) holds every function of the sources a second time, so each symbol shows up twice, the map leans on the
//! bundle and a chain walks into code that has no source of its own. Generated code (`*.pb.go`) and minified code
//! are no source a person reads either.
//!
//! A file counts as generated by what it says about itself, near its top, in the words those tools write:
//!
//! - the marker of generated code: `Code generated … DO NOT EDIT.` (Go) or `@generated` in one of the first lines;
//! - the first line of a bun bundle, `// @bun`, or the bootstrap of a webpack one (`/******/` and
//!   `webpackBootstrap` on one line);
//! - the runtime helpers esbuild puts at the top of a bundle (`var __defProp = Object.defineProperty;`), two of them
//!   at least: one alone can be written by hand;
//! - minified code: nearly all of its bytes on lines too long for a person to have written them. Hand-written code
//!   can have a few long lines (a row mapper on one line), so a share of them is not enough.

/// The lines at the top that are read for a marker.
const HEAD_LINES: usize = 40;

/// The bytes at the top that are read for a marker (a minified file has its whole text on one line).
const HEAD_BYTES: usize = 8 * 1024;

/// The lines `@generated` is looked for in (Go's `Code generated` marker may come after a licence header, so it
/// is looked for in the whole head).
const MARKER_LINES: usize = 5;

/// The helpers of an esbuild bundle, as it declares them at the top.
const ESBUILD_HELPERS: &[&str] = &[
    "var __create = Object.create",
    "var __defProp = Object.defineProperty",
    "var __getOwnPropDesc = Object.getOwnPropertyDescriptor",
    "var __getOwnPropNames = Object.getOwnPropertyNames",
    "var __getProtoOf = Object.getPrototypeOf",
    "var __hasOwnProp = Object.prototype.hasOwnProperty",
    "var __commonJS = ",
    "var __export = ",
    "var __toESM = ",
    "var __toCommonJS = ",
];

/// A line at least this long is not written by hand.
const MINIFIED_LINE: usize = 1_000;

/// A file is minified when this share (in percent) of its bytes is on such lines, and it has at least this many.
const MINIFIED_SHARE: usize = 90;
const MINIFIED_BYTES: usize = 4_096;

/// True when `text`, a source file, was written by a tool (see the module docs).
pub(super) fn generated(text: &str) -> bool {
    let head = head(text);

    marked(head) || bundled(head) || minified(text)
}

/// The top of `text`: its first [`HEAD_LINES`] lines, at most [`HEAD_BYTES`] bytes.
fn head(text: &str) -> &str {
    let mut end = text.len().min(HEAD_BYTES);

    while !text.is_char_boundary(end) {
        end -= 1;
    }

    let head = &text[..end];

    match head.match_indices('\n').nth(HEAD_LINES - 1) {
        Some((at, _)) => &head[..at],
        None => head,
    }
}

/// Go's `// Code generated … DO NOT EDIT.` in the head, or a comment of one of the first lines that is the
/// `@generated` marker (`// @generated`, ` * @generated by …`), not a sentence that mentions it.
fn marked(head: &str) -> bool {
    let go = head.lines().any(|line| {
        let line = line.trim();

        line.starts_with("// Code generated ") && line.ends_with("DO NOT EDIT.")
    });

    go || head.lines().take(MARKER_LINES).any(|line| {
        let text = line.trim().trim_start_matches(['/', '*', '#', '!']).trim_start();

        text.strip_prefix("@generated")
            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
    })
}

/// The first line of a bun bundle, the bootstrap of a webpack one, or two helpers of an esbuild one.
fn bundled(head: &str) -> bool {
    if head
        .lines()
        .next()
        .is_some_and(|line| line.trim() == "// @bun" || line.trim().starts_with("// @bun "))
    {
        return true;
    }

    if head
        .lines()
        .any(|line| line.starts_with("/******/") && line.contains("webpackBootstrap"))
    {
        return true;
    }

    head.lines()
        .filter(|line| {
            ESBUILD_HELPERS
                .iter()
                .any(|helper| line.trim_start().starts_with(helper))
        })
        .take(2)
        .count()
        == 2
}

/// Most of the bytes of `text` on lines of [`MINIFIED_LINE`] bytes or more.
fn minified(text: &str) -> bool {
    if text.len() < MINIFIED_BYTES {
        return false;
    }

    let long: usize = text.lines().map(str::len).filter(|len| *len >= MINIFIED_LINE).sum();

    long.saturating_mul(100) >= text.len().saturating_mul(MINIFIED_SHARE)
}

#[cfg(test)]
mod tests {
    use super::generated;

    #[test]
    fn a_bundle_says_so_at_its_top() {
        let esbuild = "var __create = Object.create;\nvar __defProp = Object.defineProperty;\nvar __commonJS = (cb, mod) => cb;\n\nfunction core() {}\n";
        let bun = "// @bun\nvar x = 1;\n";
        let webpack = "/******/ (() => { // webpackBootstrap\n/******/ \tvar __webpack_modules__ = {};\n";

        assert!(generated(esbuild));
        assert!(generated(bun));
        assert!(generated(webpack));
    }

    #[test]
    fn generated_code_is_marked_in_its_first_lines() {
        assert!(generated(
            "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage pb\n"
        ));
        assert!(generated(
            "/**\n * @generated by GraphQL Codegen\n */\nexport type Query = {};\n"
        ));
        assert!(generated("# @generated\nimport os\n"));
        // Go's marker may come after a licence header
        let licence = format!(
            "/*\n{}*/\n\n// Code generated by deepcopy-gen. DO NOT EDIT.\n\npackage v1\n",
            " * Copyright.\n".repeat(12)
        );
        assert!(generated(&licence));
        // a sentence at the top that names the marker is no marker
        assert!(!generated("//! Skips files marked @generated.\nfn skip() {}\n"));
        assert!(!generated("// eslint: ignore @generated files\nlet a = 1;\n"));
        // a mention further down is a comment about generated code, not the mark
        assert!(!generated(&format!(
            "{}// files marked @generated are skipped\n",
            "let a = 1;\n".repeat(10)
        )));
    }

    #[test]
    fn minified_code_is_on_lines_no_person_writes() {
        let minified = format!("{}\n", "a=1;".repeat(2_000));

        assert!(generated(&minified));
    }

    #[test]
    fn code_that_only_mentions_the_markers_or_has_long_lines_is_kept() {
        // a doc comment that names the markers, as this module's own does
        let mentions = "//! Skips bundles: `webpackBootstrap`, `// @bun` and `__defProp` at the top.\nfn skip() {}\n";
        // a hand-written file with row mappers on one line each: half of its bytes on long lines
        let mapper = format!(
            "function mapRow(row) {{ return {{ {} }}; }}\n",
            "id: row.id as string, ".repeat(60)
        );
        let rows = format!("{}{}", mapper.repeat(4), "let a = 1;\n".repeat(400));

        assert!(!generated(mentions));
        assert!(!generated(&rows));
    }

    #[test]
    fn hand_written_code_is_kept() {
        // one helper alone, or a long string among ordinary lines, is code a person wrote
        let one_helper = "var __defProp = Object.defineProperty;\nexport function core() {\n  return 1;\n}\n";
        let long_string = format!(
            "{}const DATA = \"{}\";\n{}",
            "let a = 1;\n".repeat(400),
            "x".repeat(1_200),
            "let b = 2;\n".repeat(400)
        );

        assert!(!generated(one_helper));
        assert!(!generated(&long_string));
        assert!(!generated("package main\n\nfunc main() {}\n"));
        assert!(!generated(""));
    }
}
